usage:
package main

import (
	"bytes"
	"context"
	"fmt"
	"io"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Files.New(
		context.TODO(),
		openai.FileNewParams{
			File: io.Reader(bytes.NewBuffer([]byte("Example data"))),
			Purpose: openai.CreateFileRequestPurposeAssistants,
			ExpiresAfter: openai.FileExpirationAfter{Anchor: "created_at", Seconds: 1},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
